  },
  "dataSources": {
    "ds_FW49rAx7": {
      "type": "ds.search",
      "options": {
        "query": "`corelight_idx` sensor_name=\"$sensor_name$\" eventtype IN (corelight_metrics_system, corelight_metrics_bro) \n| rename logs.*_export.lag AS export_*\n| rex field=_raw \"\\\"cpu.\\d+.temperature\\\":(?<cpu_temperature>\\d+)\" max_match=100\n| timechart values(sensor_name) as sensor avg(cpu_temperature) as \"CPU Temperature\" avg(cpu) as cpu avg(export_*) as export_* avg(logs.*.entries.per-second) as \"logs_*\" avg(files.*) as files_* avg(usage) as \"Memory Usage\" avg(usage.*) as \"* Disk Usage\"",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      },
      "name": "operations_overview_chart"
    },
    "ds_731LYlyn": {
      "type": "ds.search",
      "options": {
        "query": "`corelight_idx` sensor_name=$sensor_name$\nsourcetype IN ( corelight_corelight_metrics_bro, corelight_metrics_bro ) \n| rename logs.*_export.lag AS export_* \n| timechart span=8h avg(cpu) as cpu avg(export_*) as export_* avg(logs.*.entries.per-second) as \"logs_*\" avg(files.*) as files_* \n| fields logs_* \n| rename logs_* as * \n| rename conn AS Conn dce_rpc AS \"DCE/RPC\" dhcp AS DHCP dnp3 AS DNP3 dns AS DNS dpd AS DPD files AS Files ftp AS FTP http AS HTTP irc AS IRC kerberos AS Kerberos modbus as Modbus mysql AS MYSQL ntlm AS NTLM pe AS PE radius AS Radius rdp AS RDP rfb AS RFB sip AS SIP smb_files AS \"SMB Files\" smb_mapping AS \"SMB Mapping\" smtp AS SMTP snmp AS SNMP socks AS SOCKS software AS Software ssh AS SSH ssl AS SSL syslog AS Syslog traceroute AS Traceroute tunnel AS Tunnel weird AS Weird x509 AS X509 \n| fields _time Conn \"DCE/RPC\" DHCP DNP3 DNS DPD Files FTP HTTP IRC Kerberos Modbus MYSQL NTLM PE Radius RDP RFB SIP \"SMB Files\" \"SMB Mapping\" SMTP SNMP SOCKS Software SSH SSL Syslog Traceroute Tunnel Weird X509",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      },
      "name": "operations_log_rates"
    },
    "ds_VAWeC7Wv": {
      "type": "ds.search",
      "options": {
        "query": "|inputlookup corelight_systems",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      },
      "name": "corelight_system_csv"
    },
    "ds_8SBYYLEo": {
      "type": "ds.search",
      "options": {
        "query": "`corelight_idx` sensor_name=\"*\" `corelight_overview_timechart_iface` | eventstats max(*_mbps) as max_*_mbps| eval lblchk = if(max_in_mbps > max_out_mbps, max_in_mbps, max_out_mbs), label = case(lblchk < 1, \"Kbps\", lblchk > 1048,\"Gbps\",1=1,\"Mbps\"), \"Inbound Traffic Rate\" = round(case(label=\"Kbps\", in_mbps * 1024, label=\"Gbps\", in_mbps/1024, 1=1,in_mbps),2), \"Outbound Traffic Rate\" = round(case(label=\"Kbps\",out_mbps * 1024, label=\"Gbps\",out_mbps/1024,1=1,out_mbps),2), \"Inbound Traffic Packet Rate\" = round(in_kpps,2), \"Outbound Traffic Packet Rate\" = round(out_kpps,2) | fields _time I* O* label| fields _time label \"Inbound Traffic Rate\" \"Outbound Traffic Rate\"",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      },
      "name": "ops_in_out_mgt"
    },
    "ds_TI3KlhQH": {
      "type": "ds.search",
      "options": {
        "query": "`corelight_idx` sensor_name=\"$sensor_name$\" `corelight_overview_timechart_iface` | eventstats max(*_mbps) as max_*_mbps| eval lblchk = if(max_in_mbps > max_out_mbps, max_in_mbps, max_out_mbs), label = case(lblchk < 1, \"Kbps\", lblchk > 1048,\"Gbps\",1=1,\"Mbps\"), \"Inbound Traffic Rate\" = round(case(label=\"Kbps\", in_mbps * 1024, label=\"Gbps\", in_mbps/1024, 1=1,in_mbps),2), \"Outbound Traffic Rate\" = round(case(label=\"Kbps\",out_mbps * 1024, label=\"Gbps\",out_mbps/1024,1=1,out_mbps),2), \"Inbound Traffic Packet Rate\" = round(in_kpps,2), \"Outbound Traffic Packet Rate\" = round(out_kpps,2) | fields _time I* O* label | fields _time \"Inbound Traffic Packet Rate\" \"Outbound Traffic Packet Rate\"",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      },
      "name": "ops_packts_in_out"
    },
    "ds_OCME9MQD": {
      "type": "ds.search",
      "options": {
        "query": "`corelight_idx`  sensor_name=\"$sensor_name$\" eventtype IN (corelight_metrics_bro) \n| rename logs.*_export.lag as *_lag \n| fields *_lag \n| fieldsummary \n| table field \n| eval field=replace(field, \"_lag$\", \"\")"
      },
      "name": "ops_lag_selector_menu"
    },
    "ds_q2R1pUa7": {
      "type": "ds.search",
      "options": {
        "query": "`corelight_idx` sensor_name=\"$sensor_name$\" eventtype IN (corelight_metrics_bro)\n| timechart span=1h sum(logs.$exporter_selector$_export.lag) as \"$exporter_selector$_lag\""
      },
      "name": "ops_display_lag_chart"
    },
    "ds_u0h8fpjl": {
      "type": "ds.search",
      "options": {
        "query": "|  tstats c where `corelight_idx` by host sourcetype\n| eval Events = sum(c)\n|  stats values(host) as Sensors, by sourcetype Events",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      },
      "name": "ops_sensor_flows"
    },
    "ds_95eYxtsQ": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_FW49rAx7",
        "query": "\n|  eval total_export_sum = 0\n| foreach export_* [eval total_export_sum = total_export_sum + '<<FIELD>>']\n| stats sum(total_export_sum) as total_export_sum\n| eval formatted_total = case(total_export_sum >= 1000000, round(total_export_sum / 1000000, 2) . \"M\", total_export_sum >= 1000, round(total_export_sum / 1000, 1) . \"K\", true(), total_export_sum)\n| table formatted_total"
      },
      "name": "operations_total_lagged_logs"
    },
    "ds_EnI5g2wb": {
      "type": "ds.search",
      "options": {
        "query": "`corelight_idx` host=\"$sensor_name$\" sourcetype=corelight_corelight_service_status \n    | eval service_source = name + \" | \" + group + \" | \" + id + \" | \" + source\n    | chart c over service_source by status\n    | search false > 0\n    | rename true as healthy, false as failure\n    | sort - service_source",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      },
      "name": "operations_status"
    },
    "ds_rU0jA03R": {
      "type": "ds.search",
      "options": {
        "query": "`corelight_idx` sourcetype=corelight_conn\n| eval total_bytes = orig_bytes + resp_bytes\n| timechart span=15m sum(total_bytes) AS \"Throughput\" BY _system_name\n",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      },
      "name": "NPM_Throughput_by_Sensor"
    },
    "ds_yYfl0SXo_ds_rU0jA03R": {
      "type": "ds.search",
      "options": {
        "query": "`corelight_idx` sourcetype=corelight_conn\n| eval total_bytes = orig_bytes + resp_bytes\n| timechart span=15m sum(total_bytes) AS \"Throughput\" BY orig_cc\n",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      },
      "name": "NPM_Throughput_by_orig_country"
    },
    "ds_4VeWGckE_ds_yYfl0SXo_ds_rU0jA03R": {
      "type": "ds.search",
      "options": {
        "query": "`corelight_idx` sourcetype=corelight_conn\n| eval total_bytes = orig_bytes + resp_bytes\n| timechart span=15m sum(total_bytes) AS \"Throughput\" BY orig_cc\n",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      },
      "name": "NPM_Throughput_by_orig_country copy 1"
    }
  },
  "defaults": {
    "dataSources": {
      "ds.search": {
        "options": {
          "queryParameters": {
            "latest": "$global_time.latest$",
            "earliest": "$global_time.earliest$"
          }
        }
      }
    }
  },
  "inputs": {
